        {
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [{
    "@type": "Question",
    "name": "Why am I receiving an error message when I try to join Chipotle Rewards?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Your email may have been used to sign up for a Chipotle ordering account before (maybe you have a burrito-loving twin?). If you’ve forgotten your password, make sure to retrieve that from the digital abyss."
    }
  },{
    "@type": "Question",
    "name": "S.O.S. - I forgot to scan for points in the restaurant. What do I do?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Don't Panic! If you forgot to scan your member card on your last visit, keep your receipt handy and submit a Points Request in our app or online. Be sure to submit your Points Request within 30 days of the transaction. You can submit up to 2 Points Requests per day and up to 4 Points Requests per month.

Points Requests do not apply to orders placed before you joined Chipotle Rewards, orders placed online as a guest, purchases of a gift card, orders made through a 3rd party, with 1-800-Chipotle, or a catering order that was paid for in-person without scanning your member card."
    }
  },{
    "@type": "Question",
    "name": "Um, hello! Where are my points?!",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Points will be credited to the Rewards account upon consummation of the qualifying transaction or activity garnering points. This usually happens within 30 minutes. In certain cases, it may take twenty-four (24) hours or more for points to be added. If they’re still MIA after that time, customer service should be able to sort things out for you. Just be sure you have your receipt handy."
    }
  },{
    "@type": "Question",
    "name": "Who should I contact if I have a delivery issue?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "If you placed your order through chipotle.com or the Chipotle App our team is ready to help. For fastest service you can Chat with Pepper or call 1-800-CHIPOTLE.

For issues or questions about orders from one of our delivery partners (DoorDash, UberEats, Postmates or GrubHub) please contact them directly for help."
    }
  },{
    "@type": "Question",
    "name": "Can I schedule my delivery time?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Kinda yes, kinda no. All online or mobile orders will be delivered as soon as possible--hangry folk, rejoice--but if you place a catering order, you’ll be able to choose when you’d like to receive your large-format deliciousness. Read more about our catering options here."
    }
  },{
    "@type": "Question",
    "name": "Can I cancel my delivery after I've submitted my order?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "When you submit a delivery order, it's sent directly to our courier team and restaurant crew, so it can get cooked up and on its way to you. That makes canceling orders sort of a challenge. If you really must cancel, and you've ordered directly through our app or online, reach out to our Customer Service team through the Contact Us page. If you ordered through a partner, check your confirmation email to contact their team directly. Keep in mind that you may incur a cancelation fee."
    }
  },{
    "@type": "Question",
    "name": "Can I start a franchise or be involved in owning a restaurant in any way?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Nope. We’re not into franchising. But if you have a recommendation for a location, hit up the Make A Suggestion Tab here. You should also note that we are a publicly traded company on the NYSE. So, you can get a piece of the action by investing in CMG."
    }
  },{
    "@type": "Question",
    "name": "I can only have pasteurized dairy. Can I eat Chipotle's cheese and sour cream?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Feel free! Our shredded Monterey Jack cheese, queso, and sour cream are made with pasteurized milk."
    }
  },{
    "@type": "Question",
    "name": "We're addicted, but my kids don't like spicy foods. Does Chipotle have a meat option they can eat?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Our carnitas have black pepper only (no jalapeños or anything like that) and are very mild. Some kids aren’t into trying new things, but we're happy to offer them a sample before they commit to a meal. Just ask us."
    }
  },{
    "@type": "Question",
    "name": "How do I get cash back for my Chipotle gift card balance?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Chipotle gift cards with a balance of less than $10 are eligible to receive a payout of the unused balance. Fill out and submit the gift card cash back form linked below to request a payout of a gift card balance and Chipotle’s Customer Care team will process your request.

If you are eligible, the payout will be sent via bank transfer or check. To make a request please visit the gift card cash back page here."
    }
  },{
    "@type": "Question",
    "name": "Can I cancel my online or mobile order after I've submitted it?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "When you submit an order, it's sent directly to our restaurant crew, so it can get cooked up. That makes canceling orders sort of a challenge. If you really must cancel, and you've ordered directly through our app or online, reach out to our Customer Service team through the Contact Us page. If you ordered through a partner, check your confirmation email to contact their team directly. Keep in mind that you may incur a cancelation fee."
    }
  }]
}
